package app.rwun;
import android.content.*;import android.os.OutcomeReceiver;import java.time.ZoneOffset;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Explicit, versioned upserts. Writing never requires read permission. */
final class HealthExport {
 static final String[] PERMISSIONS={"android.permission.health.WRITE_EXERCISE","android.permission.health.WRITE_DISTANCE"};
 private static final AtomicBoolean BUSY=new AtomicBoolean();
 static boolean granted(Context c){return HealthAccess.granted(c,PERMISSIONS);}static boolean busy(){return BUSY.get();}
 interface Writer{CompletableFuture<Void> insert(HealthWritePlan plan,long version);}
 static CompletableFuture<String> write(Context c,String id,String fingerprint){if(android.os.Build.VERSION.SDK_INT<34||!HealthAccess.available(c))return HealthSync.failed(new IllegalStateException("Health Connect requires Android 14 or newer."));return write(c,id,fingerprint,(plan,version)->Api34.insert(c,plan,version));}
 static CompletableFuture<String> write(Context c,String id,String fingerprint,Writer writer){CompletableFuture<String> result=new CompletableFuture<>();if(!granted(c)){result.completeExceptionally(new SecurityException("Grant exercise and distance write access first."));return result;}if(!BUSY.compareAndSet(false,true)){result.completeExceptionally(new IllegalStateException("An export is already in progress."));return result;}ExecutorService executor=Executors.newSingleThreadExecutor();HealthTransfer.bound(result);result.whenComplete((v,e)->{BUSY.set(false);executor.shutdown();});executor.execute(()->{if(result.isDone())return;try{HealthWritePlan plan=HealthWritePlan.find(c,new RunStore(c),id);if(!plan.fingerprint().equals(fingerprint))throw new IllegalStateException("The recording changed. Review it again before writing to Health Connect.");if(!granted(c))throw new SecurityException("Health Connect write access was revoked.");long version=version(c,plan);writer.insert(plan,version).whenComplete((v,e)->{if(e!=null)result.completeExceptionally(e);else result.complete("Activity written to Health Connect. Repeating updates the same records.");});}catch(Exception e){result.completeExceptionally(e);}});return result;}
 static synchronized long version(Context c,HealthWritePlan plan){SharedPreferences state=c.getSharedPreferences("health-connect-exports",Context.MODE_PRIVATE);String key=RaceData.digest(plan.id()),hash=plan.fingerprint();long previous=state.getLong(key+":version",0);if(hash.equals(state.getString(key+":hash",""))&&previous>0)return previous;long next=Math.max(previous+1,System.currentTimeMillis());if(!state.edit().putLong(key+":version",next).putString(key+":hash",hash).commit())throw new IllegalStateException("Could not save export identity. Nothing was sent to Health Connect.");return next;}
 @android.annotation.TargetApi(34) static final class Api34 {
  static List<android.health.connect.datatypes.Record> records(HealthWritePlan p,long version){List<android.health.connect.datatypes.Record> out=new ArrayList<>();int type=p.walking()?android.health.connect.datatypes.ExerciseSessionType.EXERCISE_SESSION_TYPE_WALKING:p.indoor()?android.health.connect.datatypes.ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING_TREADMILL:android.health.connect.datatypes.ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING;
   out.add(new android.health.connect.datatypes.ExerciseSessionRecord.Builder(metadata("rwun-session:",p,version),p.start(),p.end(),type).setTitle(p.title()).setStartZoneOffset(ZoneOffset.UTC).setEndZoneOffset(ZoneOffset.UTC).setNotes("Active time: "+p.activeSeconds()+" seconds. Session interval includes pauses. Distance: "+p.distanceSource()+". No route or heart-rate samples exported.").build());
   if(p.km()!=null)out.add(new android.health.connect.datatypes.DistanceRecord.Builder(metadata("rwun-distance:",p,version),p.start(),p.end(),android.health.connect.datatypes.units.Length.fromMeters(p.km()*1000)).setStartZoneOffset(ZoneOffset.UTC).setEndZoneOffset(ZoneOffset.UTC).build());return out;}
  private static android.health.connect.datatypes.Metadata metadata(String prefix,HealthWritePlan p,long version){return new android.health.connect.datatypes.Metadata.Builder().setClientRecordId(prefix+p.id()).setClientRecordVersion(version).setRecordingMethod(prefix.equals("rwun-distance:")&&(p.distanceSource().equals("Machine entered")||p.distanceSource().equals("Corrected totals")||p.distanceSource().equals("Manually corrected distance"))?android.health.connect.datatypes.Metadata.RECORDING_METHOD_MANUAL_ENTRY:android.health.connect.datatypes.Metadata.RECORDING_METHOD_ACTIVELY_RECORDED).build();}
  static CompletableFuture<Void> insert(Context c,HealthWritePlan p,long version){CompletableFuture<Void> result=new CompletableFuture<>();var manager=c.getSystemService(android.health.connect.HealthConnectManager.class);if(manager==null)throw new IllegalStateException("Health Connect is unavailable.");manager.insertRecords(records(p,version),c.getMainExecutor(),new OutcomeReceiver<android.health.connect.InsertRecordsResponse,android.health.connect.HealthConnectException>(){public void onResult(android.health.connect.InsertRecordsResponse response){result.complete(null);}public void onError(android.health.connect.HealthConnectException error){result.completeExceptionally(error);}});return result;}
 }
}
